function telegramJournalReply({ body, botUsername, userUsername }) {
  if (
    typeof botUsername !== "string" ||
    !botUsername.trim() ||
    botUsername === "YOUR_BOT_USERNAME" ||
    typeof userUsername !== "string" ||
    !userUsername.trim() ||
    userUsername === "YOUR_USERNAME"
  )
    throw new Error("Set the bot and user usernames without @");
  const message = body?.message;
  const reply = message?.reply_to_message;
  if (
    !message ||
    !reply ||
    message.from?.username !== userUsername ||
    reply.from?.username !== botUsername ||
    typeof message.text !== "string"
  )
    return { accepted: false, entry: "", date: "", values: [] };
  if (typeof reply.text !== "string" || !reply.text.includes(":"))
    throw new Error("The bot prompt must contain a colon followed by the journal date");
  const date = reply.text.split(":")[1].replace(/\s/g, "");
  const entry = message.text;
  return { accepted: true, entry, date, values: [[entry, date]] };
}

const result = telegramJournalReply({
  body: $input.first().json,
  botUsername: "YOUR_BOT_USERNAME",
  userUsername: "YOUR_USERNAME",
});
if (!result.accepted) return [];
return [{ json: { entry: result.entry, date: result.date } }];
